    return MapEntry(entry.key, entry.value.reduce((a, b) => a + b) / entry.value.length);
  }).toList();

  avgProfits.sort((a, b) => b.value.compareTo(a.value));

  return avgProfits.take(3).map((entry) => entry.key).toList();
}

