 To add IDs to the HTML elements in your code, you can use the `htmlFor` attribute with a ref or use the `id` attribute directly on the element. Here's how you can modify your code to achieve that:

```jsx
import { observer, useRef } from "mobx-react";
import { CreateObjectModel } from "./CreateObjectModel"; // Assuming this is your model file

export const CreateObjectView = observer(({ model }: { model: CreateObjectModel }) => {
  const assetInputRef = useRef<HTMLInputElement>(null);

  const handleSelectAsset = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.checked && assetInputRef.current) {
      model.createObject(assetInputRef.current.value as string).then();
      model.setSelectedAsset(assetInputRef.current.value);
    }
  };

  return (
    <div className="CreateObjectView">
      <label htmlFor="assets-list">Assets</label>
      <input type="checkbox" id="assets-list" />
      <ul id="assets-list">
        {model.availableAssets.map((asset, index) => (
          <li key={index}>
            <input
              type="radio"
              id={`asset-${index}`}
              name="asset"
              ref={index === model.selectedIndex ? assetInputRef : null}
              onChange={handleSelectAsset}
              value={asset}
            />
            <label htmlFor={`asset-${index}`}>{asset}</label>
          </li>
        ))}
      </ul>
      <button onClick={() => model.cleanupScene()}>Cleanup scene</button>
    </div>
  );
});
```

In the example above, I added an `id` attribute to the unordered list and each list item. Also, I used a ref for the input element that gets selected when an asset is chosen. The `ref` is assigned to the input element based on the current `selectedIndex` of the `model`. The `htmlFor` attribute is used on the label to associate it with the corresponding radio button.

