function findNestedEntry(obj, strKey) {
  // Split the keys into an array using '.' as delimiter
  const keys = strKey.split('.');

  let currentObj = obj;
  for (let i = 0; i < keys.length; i++) {
    if (!currentObj || !currentObj[keys[i]]) {
      return undefined;
    }
    currentObj = currentObj[keys[i]];
  }

  return currentObj;
}

