const myObject = {
  a: {
    b: {
      c: 'Hello',
      d: 'World'
    },
    e: 'Foo'
  },
  f: 'Bar'
};

console.log(findNestedEntry(myObject, 'a.b.c')); // Output: 'Hello'
console.log(findNestedEntry(myObject, 'a.e')); // Output: 'Foo'
console.log(findNestedEntry(myObject, 'nonExistentKey')); // Output: undefined
```

