```typescript
const separateAxisTest = (a: THREE.Vector3, b: THREE.Vector3, epsilon: number): boolean => {
  const [axMin, axMax] = [a.x, a.x + a.length()];
  const [bxMin, bxMax] = [b.x, b.x + b.length()];

  if (axMax < bxMin) return true;
  if (bxMax < axMin) return true;

  const [ayMin, ayMax] = [a.y, a.y + a.length()];
  const [byMin, byMax] = [b.y, b.y + b.length()];

  if (ayMax < byMin) return true;
  if (byMax < ayMin) return true;

  const [azMin, azMax] = [a.z, a.z + a.length()];
  const [bzMin, bzMax] = [b.z, b.z + b.length()];

  if (azMax < bzMin) return true;
  if (bzMax < azMin) return true;

  return false;
};
```

